namespace OverlaySample
{
    public partial class MainWindow : Window
    {
        private readonly Form _targetForm;

        public MainWindow()
        {
            InitializeComponent();

            // Determine the target window
            _targetForm = Form.ActiveForm;

            // Set the overlay's location and size to match the target window
            Left = _targetForm.Left;
            Top = _targetForm.Top;
            Width = _targetForm.Width;
            Height = _targetForm.Height;

            // Make the overlay transparent
            AllowsTransparency = true;
            Background = Brushes.Transparent;

            // Set the overlay's window style
            WindowStyle = WindowStyle.None;
            Topmost = true;

            // Attach the overlay to the target window
            var source = PresentationSource.FromVisual(this) as HwndSource;
            source.AddHook(WndProc);
        }

        private IntPtr WndProc(IntPtr hwnd, int msg, IntPtr wParam, IntPtr lParam, ref bool handled)
        {
            // Handle mouse and keyboard events
            switch (msg)
            {
                // ...
            }

            return IntPtr.Zero;
        }
    }
}
