% Define the number of rolls
N = 1000;

% Initialize variables
count = 0;
p = zeros(1,6);

% Simulate N rolls of a dice
for i = 1:N
   % Roll the dice
   roll = randi([1,6]);
   
   % Count the number of times a 6 is rolled
   if roll == 6
       count = count + 1;
   end
   
   % Calculate the probability of rolling each number
   for j = 1:6
      p(j) = sum(randi([1,6],1,N) == j)/N;
   end
end

% Calculate the probability of rolling a 6
p6 = count/N;

% Display results
disp(['Probability of rolling a 6 in ',num2str(N),' rolls is ',num2str(p6)]);
disp(['Probability of rolling each number is ',num2str(p)]);


