```.cpp
#include<iostream>
#include<ctime>
using namespace std;

int main(){
    srand(time(NULL));  //initializing random seed
    int minTemp=65, maxTemp=85, avgTemp=0, tempSum=0;

    for(int i=1; i<=7; i++){
        int temp = (rand() % (maxTemp - minTemp + 1)) + minTemp;
        tempSum += temp;
    }

